def maxCandies(status, candies, keys, containedBoxes, initialBoxes):
    from collections import deque

    queue = deque(initialBoxes)
    visited = set()
    collected_candies = 0
    available_keys = set()

    while queue:
        current_box = queue.popleft()

        if current_box in visited:
            continue

        if status[current_box] == 0 and current_box not in available_keys:
            queue.append(current_box)
            continue

        visited.add(current_box)
        collected_candies += candies[current_box]
        available_keys.update(keys[current_box])

        for box in containedBoxes[current_box]:
            if box not in visited:
                queue.append(box)

    return collected_candies
